window.docContents[88].resolve({"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Representation-of-a-Lie-algebra/#Chapter2___Definition2___9___7":{"contents":"Definition 2.9.7. A representation of a Lie algebra \\mathfrak{g} is a vector space V with a homomorphism of Lie algebras \\rho : \\mathfrak{g} \\longrightarrow \\operatorname{End} V.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.9. Lie algebras\tRepresentation of a Lie algebra","header":"Representation of a Lie algebra","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Representation-of-a-Lie-algebra/#Chapter2___Definition2___9___7"},"/4___-Representations-of-finite-groups___-Basic-results/4___2___-Characters/Characters-of-irreducible-representations-form-a-basis-of-class-functions/#Chapter4___Theorem4___2___1":{"contents":"Theorem 4.2.1. If the characteristic of k does not divide |G|, characters of irreducible representations of G form a basis in the space F_c(G, k).\nProof. By the Maschke theorem, k[G] is semisimple, so by Theorem 3.6.2, the characters are linearly independent and are a basis of (A/[A, A])^*, where A = k[G]. It suffices to note that, as vector spaces over k,\n\n(A/[A, A])^* \\cong \\{\\varphi \\in \\operatorname{Hom}_k(k[G], k) \\mid gh - hg \\in \\ker \\varphi \\ \\forall g, h \\in G\\}\n\n\\cong \\{f \\in F(G, k) \\mid f(gh) = f(hg) \\ \\forall g, h \\in G\\},\n\nwhich is precisely F_c(G, k). \\square\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.2. Characters\tCharacters of irreducible representations form a basis of class functions","header":"Characters of irreducible representations form a basis of class functions","id":"/4___-Representations-of-finite-groups___-Basic-results/4___2___-Characters/Characters-of-irreducible-representations-form-a-basis-of-class-functions/#Chapter4___Theorem4___2___1"},"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Section-3___10___-Representations-of-tensor-products-___-heading-and-setup/#Chapter3___Introduction_to_3___10___heading-1":{"contents":"Let A, B be algebras. Then A \\otimes B is also an algebra, with multiplication (a_1 \\otimes b_1)(a_2 \\otimes b_2) = a_1 a_2 \\otimes b_1 b_2.\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.10. Representations of tensor products\tSection 3.10: Representations of tensor products — heading and setup","header":"3.10. Representations of tensor products","id":"/3___-General-results-of-representation-theory/3___10___-Representations-of-tensor-products/Section-3___10___-Representations-of-tensor-products-___-heading-and-setup/#Chapter3___Introduction_to_3___10___heading-1"},"/5___-Representations-of-finite-groups___-Further-results/5___10___-Frobenius-reciprocity/#chapter-05___section-5-10":{"contents":"\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results","header":"5.10. Frobenius reciprocity","id":"/5___-Representations-of-finite-groups___-Further-results/5___10___-Frobenius-reciprocity/#chapter-05___section-5-10"}});
